function text(v) {
  if (Array.isArray(v)) return v.join(' ').toLowerCase();
  return String(v || '').toLowerCase();
}
function pickTier(row) {
  const urgency = text(row.urgency);
  const role = text(row.role);
  const volume = text(row.volume);
  const lane = text(row.list_type) + ' ' + text(row.notes);
  if (lane.includes('all signals') || lane.includes('all lanes') || role.includes('fund') || volume.includes('enterprise')) {
    return ['exclusive', 'Exclusive Territory', 'All-lane or enterprise/exclusivity signal. Match to capped one-buyer territory access.'];
  }
  if (lane.includes('probate')) return ['specialty', 'Probate Premium', 'Probate is a premium court-scrape lane. Recommend the specialty pull with source context and tight list size.'];
  if (lane.includes('pre-foreclosure') || lane.includes('foreclosure')) return ['specialty', 'Pre-Foreclosure Premium', 'Pre-foreclosure is a time-sensitive court/recorder specialty lane.'];
  if (lane.includes('code')) return ['specialty', 'Code Violations List', 'Code violations belong in the premium specialty lane because source freshness drives value.'];
  if (lane.includes('permit')) return ['specialty', 'Active Permits Distress', 'Active permits/damage is a premium operational distress lane.'];
  if (lane.includes('debt') || lane.includes('breaking') || volume.includes('500') || volume.includes('1500')) {
    return ['specialty', 'The Breaking Point', 'Debt/quality/volume signals point to a tighter pressure-signal subset.'];
  }
  if (lane.includes('auction') || urgency.includes('this week') || urgency.includes('need it now') || urgency.includes('24') || urgency.includes('48')) {
    return ['hotsheet', 'Imminent Auction Hot Sheet', 'Urgent timing points to verified auction-date records and fast action.'];
  }
  if (lane.includes('not sure') || lane.includes('multi') || role.includes('team') || role.includes('acquisitions')) {
    return ['bundle', 'Market Dominance', 'Multi-lane or team signal. Recommend the all-lanes bundle for one market.'];
  }
  if (lane.includes('individual') || lane.includes('homeowner')) return ['entry', 'Active Homeowner List', 'Foundational homeowner lane. Start with the entry pull.'];
  if (lane.includes('absentee')) return ['entry', 'Absentee Owner List', 'Foundational absentee-owner lane. Start with the entry pull.'];
  if (lane.includes('equity')) return ['entry', 'High-Equity Owners List', 'Foundational high-equity lane. Start with the entry pull.'];
  if (lane.includes('lien')) return ['entry', 'Liens Watchlist', 'Foundational lien lane. Start with the entry pull.'];
  return ['entry', 'Curated Distress List', 'No premium/urgent signal. Default to the foundational curated list.'];
}
const rows = Array.isArray($json) ? $json : ($json.data || ($json.id ? [$json] : []));
return rows.map((row) => {
  const [tier_key, recommended_tier, recommendation_note] = pickTier(row);
  return { json: { ...row, tier_key, recommended_tier, recommendation_note } };
});
